// Real process UI; browser-local demonstration only.
steps.splice(0,steps.length,'主码过站','电芯绑定','仪器测试','SN 绑定','包装绑定');
let wfStage=0,wfTab='work',wfCode='',wfChecked=false;
let wfUser={name:'张伟',id:'EMP-008'};try{let user=JSON.parse(sessionStorage.getItem('mes-demo-user')||'null');if(user?.name&&user?.id)wfUser=user;let stage=Number(sessionStorage.getItem('mes-workstation')||0);if(Number.isInteger(stage)&&stage>=0&&stage<5)wfStage=stage}catch{}
const WFKEY='power-mes-workflow-v2';let units=[];try{units=JSON.parse(localStorage.getItem(WFKEY)||'[]')}catch{}if(!Array.isArray(units))units=[];
function keep(){localStorage.setItem(WFKEY,JSON.stringify(units))}function activeUnit(){return units.find(u=>u.main===wfCode||u.sn===wfCode)}function wfEvent(u,title,note){u.history.push({title,note,time:new Date().toLocaleTimeString('zh-CN',{hour12:false})})}function stationId(){return 'A01-0'+(wfStage+1)}
function station(){let stages=['01 主码过站','02 绑定电芯','03 仪器测试','04 绑定 SN','05 绑定包装'];return `<div class="stationbar"><div><b style="font-size:19px">◈ 智造 MES / 工位终端</b><p class="sub">${stationId()} · ${steps[wfStage]}</p></div><div class="actions">${button('⇄ 切换工位',"wfChooseStation()")}${button('⚙ 设置',"configureServer()")}${button(escapeHtml(wfUser.name)+' · '+escapeHtml(wfUser.id)+' ▾',"wfUserMenu()")}</div></div><div class="content">${heading(steps[wfStage]+'工作站','主码贯穿前段生产，绑定 SN 后用于成品履历及包装追溯')}${typeof wfJob==='undefined'?'':wfOrderSummary()}<div class="tabs">${['现场作业','SOP 指导书','工位消息','过站记录'].map((x,i)=>button(x,`wfTab='${['work','sop','messages','records'][i]}';render()`,wfTab===['work','sop','messages','records'][i]?'active':'')).join('')}</div>${wfTab==='work'?wfWork()+(typeof scanLogs==='undefined'?'':wfRecentPanel()):wfTab==='sop'?wfSop():wfTab==='messages'?panel('工位消息',msgs.map((m,i)=>`<div class="lineitem"><div class="fill"><b>${escapeHtml(m.title)}</b><p class="sub">${escapeHtml(m.text)}</p></div>${badge(m.read?'已确认':m.type)}${button('查看',`messageDetail(${i})`)}</div>`).join('')):panel('全过程记录',wfRecords())}<p class="hint">界面原型 · 本机浏览器保存演示记录 · 不接收真实仪器数据</p></div>`}
function wfSop(){let descriptions=['扫描产品主码建立生产记录，检查主码完整、清晰且唯一。','先扫描主码调出产品，再扫描电芯码，核对电芯型号及批次后绑定。','产品接入测试仪；在仪器自带屏幕或扫码端扫描主码启动测试。MES 自动接收 PASS 和 FAIL 及全部测试记录。','测试 PASS 后先扫描主码，再扫描成品 SN，确认映射后绑定。','先扫描成品 SN，核对主码、电芯、测试和绑定记录，再扫描包装码完成绑定。'];return panel('SOP · '+steps[wfStage]+' V1.0',sopDrawing()+`<h2 style="margin-top:20px">标准操作</h2><p>${descriptions[wfStage]}</p><div class="notice">${wfStage===2?'测试在仪器端启动，MES 页面只接收与展示记录。':'扫描结果应与当前工单、产品型号及工位一致。'}</div>`)}
function wfWork(){let u=activeUnit(),valid=u&&(wfStage===4?u.sn===wfCode:u.main===wfCode),expect=wfExpected(),sequence={0:'扫描主码 → 自动过站',1:'主码 → 电芯码 → 自动绑定',3:'主码 → 成品 SN → 自动绑定',4:'成品 SN → 自动展示履历 → 包装码 → 自动绑定'}[wfStage];return `<div class="stationlayout"><div>${wfSop()}</div><div>${panel('扫码作业',`<div class="panelhead"><span class="sub">${sequence}</span>${badge('等待'+expect)}</div><label class="field" for="wfScan">请扫描${expect}<input id="wfScan" class="auto-scan" autocomplete="off" spellcheck="false" placeholder="请扫描${expect}…" autofocus onkeydown="if(event.key==='Enter'||event.key==='Tab'){event.preventDefault();wfAutoScan()}"></label><p class="hint">使用同一把扫码枪、同一个输入框；条码结束符为 Enter 或 Tab 时自动处理。</p><div class="summaryrow"><span class="sub">当前${wfStage===4?'SN':'主码'}</span><b>${wfCode?escapeHtml(wfCode):'等待扫描'}</b></div>${valid?`<div class="statusbox ${wfStage>=3&&!lastPass(u)?'fail':''}"><h2>${wfStage>=3&&!lastPass(u)?'测试未合格，禁止绑定':wfAwaiting()?'已识别产品 · 请继续扫描'+expect:'本次操作已处理'}</h2><p class="sub">${wfAwaiting()?'保持当前产品关联，直接扫描下一条码即可。':'可直接扫描下一台产品。'}</p></div>`:wfCode?'<div class="statusbox fail">条码不存在或不符合当前工位，请重新扫描。</div>':'<div class="statusbox"><h2>等待扫描'+expect+'</h2><p class="sub">扫描完成后自动识别、校验并处理。</p></div>'}${button(wfStage===4?'重新扫 SN':'重新扫主码',"wfResetScan()")}`)}${valid?panel('当前产品信息',detailRows([['主码',escapeHtml(u.main)],['电芯码',escapeHtml(u.cell)||'未绑定'],['成品 SN',escapeHtml(u.sn)||'未绑定'],['包装码',escapeHtml(u.pack)||'未绑定'],['最新测试',u.tests.length?badge(u.tests.at(-1).result):'未测试']])+(wfStage===4?`<h3 style="margin:18px 0">完整生产履历</h3>${wfHistory(u)}`:'')):''}</div></div>`}
function wfLookup(){let c=$('#wfScan').value.trim();if(!c){toast('请扫描条码');return}wfCode=c;wfChecked=false;if(wfStage===0){let u=units.find(x=>x.main===c);if(u){toast('主码已过站，保留原记录，避免重复计数')}else{u={order:wfJob.id,main:c,cell:'',sn:'',pack:'',tests:[],history:[]};wfEvent(u,'主码过站','工位 A01-01 · '+wfUser.name+' '+wfUser.id);units.push(u);keep();toast('主码过站成功')}}render()}
function lastPass(u){return u.tests.length&&u.tests[u.tests.length-1].result==='PASS'}
function wfBind(kind,scannedCode){let u=activeUnit(),c=scannedCode||'';if(!u||!c){toast('请先扫描关联条码');return}if([u.main,u.cell,u.sn].includes(c)){toast('条码与已有关联码冲突，请核对');return}if(kind==='cell'){if(u.cell){toast('该主码已绑定电芯');return}if(units.some(x=>x.cell===c)){toast('该电芯码已被绑定');return}u.cell=c;wfEvent(u,'绑定电芯',c+' · '+wfUser.name+' '+wfUser.id)}else if(kind==='sn'){if(!lastPass(u)||!u.cell){toast('前序未合格，禁止绑定 SN');return}if(u.sn||units.some(x=>x.sn===c)){toast('SN 重复或产品已有 SN');return}u.sn=c;wfEvent(u,'主码绑定 SN',c+' · '+wfUser.name+' '+wfUser.id)}else{if(!u.sn||!lastPass(u)||!wfChecked){toast('请核对完整履历并确认；产品必须测试合格');return}if(u.pack){toast('产品已绑定包装码');return}u.pack=c;wfEvent(u,'SN 绑定包装码',c+' · '+wfUser.name+' '+wfUser.id+' · 流程完成')}keep();render();toast('绑定成功（演示记录）')}
function wfTest(result){let u=activeUnit();if(!u||!u.cell){toast('前序未完成，测试请求应被拦截');return}if(u.sn||u.pack){toast('已流转产品的补测需异常处理，演示中禁止直接修改');return}let t={timestamp:Date.now(),device:'ATE-001',record:'R-'+Date.now(),result,time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),voltage:5.08,current:result==='PASS'?2.96:1.24};u.tests.push(t);wfEvent(u,'仪器自动上传 '+result,'ATE-001 · '+t.record+' · '+t.current+' A');keep();render();toast(result==='PASS'?'测试 PASS 已自动记录，可以进入 SN 绑定':'测试 FAIL 已自动记录，后续绑定被拦截')}
function wfHistory(u){return `<div class="timeline">${u.history.map(h=>`<div class="event"><time>${h.time}</time><b>${escapeHtml(h.title)}</b><p>${escapeHtml(h.note)}</p></div>`).join('')}</div>`}function wfRecords(){return table(['主码','电芯码','SN','测试次数 / 最新结果','包装码'],units.map(u=>[escapeHtml(u.main),escapeHtml(u.cell)||'—',escapeHtml(u.sn)||'—',u.tests.length+' / '+(u.tests.length?badge(u.tests.at(-1).result):'未测试'),escapeHtml(u.pack)||'—']))}
renderers.routes=function(){return heading('工艺路线','按实际条码流转配置，主码与成品 SN 接续追溯')+panel('充电宝标准流程 · V2.0',route(0)+table(['顺序','工位','扫描顺序 / 操作','放行要求'],[['01','主码过站','扫描主码','主码唯一，保存过站记录'],['02','电芯绑定','主码 → 电芯码','主码已过站，电芯码未被占用'],['03','仪器测试','插入仪器 → 仪器扫主码 → 自动测试','自动记录 PASS / FAIL，PASS 才允许下一站'],['04','SN 绑定','主码 → 成品 SN','电芯已绑定，最新测试 PASS，SN 唯一'],['05','包装绑定','成品 SN → 查看完整履历 → 包装码','SN 有效，前序完成，未重复绑定包装']])+`<div class="notice" style="margin-top:20px">测试由仪器自带屏幕启动，MES 接收所有测试结果。失败记录保留，后续复测新增记录。</div>`,button('体验完整流程',"setMode('station')"))};
renderers.trace=function(){return heading('条码与全程追溯','主码或 SN 查询：电芯、仪器测试、SN 映射与包装关联')+panel('查询产品',`<div class="scanbox"><input id="wfTrace" placeholder="输入主码或成品 SN">${button('查询',"wfTraceSearch()",'primary')}</div>`)+`<div id="wfTraceResult">${panel('当前演示记录',wfRecords())}</div>`};function wfTraceSearch(){let c=$('#wfTrace').value.trim(),u=units.find(x=>x.main===c||x.sn===c);$('#wfTraceResult').innerHTML=u?panel('全部绑定信息',detailRows([['主码',escapeHtml(u.main)],['电芯码',escapeHtml(u.cell)],['SN',escapeHtml(u.sn)],['包装码',escapeHtml(u.pack)]])+wfHistory(u)):panel('查询结果','未找到该条码，请先在平板端按 01 → 05 完成演示。')}
renderers.api=function(){return heading('仪器接口与上传记录','仪器扫描主码自动开始测试，PASS 与 FAIL 全部自动上传')+`<div class="notice">接口设计示例，当前原型不提供真实接收服务。仪器程序启动前应向 MES 校验主码及前序状态。</div><div class="gridhalf">${panel('测试结果事件 · POST /api/v1/test-results',`<div class="code">${escapeHtml(JSON.stringify({record_id:'ATE001-20261015-00128',task_id:'TT-000128',main_code:'MC261015000128',device_id:'ATE-001',station_id:'A01-03',result:'PASS',measurements:[{item:'voltage',value:5.08,unit:'V'},{item:'current',value:2.96,unit:'A'}],raw_log:'原始测试记录附件引用'},null,2))}</div>`)}${panel('接收规则',detailRows([['身份校验','设备与工位凭证'],['前序校验','主码过站 + 电芯已绑定'],['记录去重','record_id 唯一'],['产品关联','主码 + 本次测试任务'],['数据保留','PASS / FAIL 都保存，复测不覆盖'],['后序放行','最新有效测试必须 PASS']]))}</div>`+panel('仪器上传记录',table(['主码','记录编号','结果','电流','时间'],units.flatMap(u=>u.tests.map(t=>[escapeHtml(u.main),t.record,badge(t.result),t.current+' A',t.time]))))};
renderers.warehouse=function(){return heading('包装绑定','扫描 SN 查看前段全部信息，然后扫描包装码完成绑定',button('进入包装工位',"wfStage=4;wfTab='work';setMode('station')",'primary'))+panel('包装关联记录',wfRecords())};
renderers.stations=function(){return heading('产线与工位','五个固定工位；测试操作在仪器自带屏幕完成')+panel('A01 · 充电宝生产线',`<div class="machinegrid">${steps.map((s,i)=>`<div class="machine"><div class="panelhead"><b>A01-0${i+1}</b>${badge('在线')}</div><h2>${s}</h2><p class="sub">${i===2?'仪器自带屏幕 · 自动上传':'安卓平板 · 扫码 + SOP + 消息'}</p>${button('查看工位',`wfStage=${i};wfCode='';wfTab='work';setMode('station')`)}</div>`).join('')}</div>`)};
render();

function wfChooseStation(){modal('切换工位',`<p class="sub">选择当前平板使用的工位，确认后仅显示该工位的作业界面。</p><div class="field" style="margin-top:16px"><label for="stationChoice">生产工位</label><select id="stationChoice">${steps.map((s,i)=>`<option value="${i}" ${i===wfStage?'selected':''}>A01-0${i+1} · ${s}</option>`).join('')}</select></div><div class="notice" style="margin-top:16px">切换将清空当前扫码输入，已保存的生产记录保留。</div>`,button('取消','closeModal()')+button('确认切换',"wfSwitchStation()",'primary'))}
function wfSwitchStation(){let i=Number($('#stationChoice').value);if(!Number.isInteger(i)||i<0||i>=steps.length)return;wfStage=i;wfCode='';wfChecked=false;wfTab='work';sessionStorage.setItem('mes-workstation',String(i));closeModal();render();toast('已切换至 '+stationId()+' '+steps[i])}
function wfUserMenu(){modal('当前登录用户',detailRows([['姓名',escapeHtml(wfUser.name)],['工号',escapeHtml(wfUser.id)],['当前工位',stationId()+' · '+steps[wfStage]],['账号状态','原型演示账号']]),button('返回管理后台',"closeModal();setMode('pc')")+button('切换用户',"wfLoginModal()",'primary'))}
function wfLoginModal(){modal('登录工位端',`<div class="notice">原型演示登录，不连接真实账号系统；密码不会保存。</div><label class="field">员工姓名<input id="wfName" placeholder="输入员工姓名"></label><label class="field" style="margin-top:14px">工号<input id="wfEmp" placeholder="输入员工工号"></label><label class="field" style="margin-top:14px">演示密码<input id="wfPwd" type="password" placeholder="任意非空演示密码"></label>`,button('取消','closeModal()')+button('登录',"wfLogin()",'primary'))}
function wfLogin(){let name=$('#wfName').value.trim(),id=$('#wfEmp').value.trim(),pwd=$('#wfPwd').value;if(!name||!id||!pwd){toast('请填写姓名、工号及演示密码');return}wfUser={name,id};sessionStorage.setItem('mes-demo-user',JSON.stringify(wfUser));wfCode='';wfChecked=false;closeModal();render();toast('已切换登录用户：'+name)}
demoLogin=function(m){let id=$('#loginUser').value.trim();if(!id||!$('#loginPass').value){toast('请输入工号和演示密码');return}let people={'EMP-008':'张伟','EMP-012':'刘敏','EMP-016':'李工','EMP-001':'王主管'};wfUser={id,name:people[id]||id};sessionStorage.setItem('mes-demo-user',JSON.stringify(wfUser));page='overview';setMode(m)};
render();

// A device must have its MES server configured before opening station views.
const SERVERKEY='power-mes-server';let mesServer='';let serverEdit=false,serverError='';
function normalizeServer(input){let value=input.trim();if(!value)throw Error('请输入 MES 服务器地址');if(!/^[a-z][a-z0-9+.-]*:\/\//i.test(value))value='http://'+value;let u;try{u=new URL(value)}catch{throw Error('地址格式不正确，例如 192.168.0.197:8080')}if(!['http:','https:'].includes(u.protocol))throw Error('仅支持 HTTP 或 HTTPS 地址');if(u.username||u.password)throw Error('地址中不能包含账号或密码');if(u.search||u.hash||(u.pathname&&u.pathname!=='/'))throw Error('请填写服务器基础地址，不包含路径、查询参数或片段');if(!u.hostname||!u.hostname.includes('.')&&u.hostname!=='localhost'&&!u.hostname.includes(':'))throw Error('请填写有效的 IP 地址或域名');return u.origin}
try{let saved=localStorage.getItem(SERVERKEY);if(saved)mesServer=normalizeServer(saved)}catch{}
const configuredStation=station;
station=function(){if(!mesServer||serverEdit)return serverSetup();return wfStage===2?instrumentStation():configuredStation()};
function serverSetup(){return `<div class="stationbar"><div><b style="font-size:19px">◈ 智造 MES / 工位终端</b><p class="sub">设备初始化 · 服务器配置</p></div><span style="font-size:12px;color:#9bb2c4">${mesServer?'修改服务器':'首次使用'}</span></div><div class="content"><div class="login" style="min-height:73vh"><section class="loginbox" style="max-width:530px"><div class="eyebrow">WORKSTATION SETUP / 01</div><h1>${mesServer?'服务器设置':'连接工厂 MES 服务器'}</h1><p class="sub" style="margin:12px 0 25px">${mesServer?'查看或修改当前设备的 MES 服务器地址。保存后返回当前工位。':'首次使用，请设置后台服务地址。地址将保存在当前设备，后续自动使用。'}</p><label class="field" for="serverAddress">MES 服务器地址<input id="serverAddress" type="text" autocomplete="off" spellcheck="false" value="${escapeHtml(mesServer)}" placeholder="192.168.0.197:8080" onkeydown="if(event.key==='Enter')saveServer()"></label><p class="hint" style="margin-top:0">支持 192.168.0.197:8080 或 https://mes.example.com</p>${serverError?`<div class="statusbox fail" role="alert">${escapeHtml(serverError)}</div>`:''}<div class="notice" style="margin-top:22px">工位设备需要能够访问该地址；局域网部署时，通常连接同一工厂网络。</div><div class="summaryrow"><span class="sub">配置状态</span>${badge(mesServer?'地址已保存':'尚未配置')}</div><div class="summaryrow"><span class="sub">连接状态</span><span style="color:#a57422">未验证（界面演示）</span></div><div style="margin-top:23px">${button(mesServer?'保存服务器地址':'保存并进入工位',"saveServer()",'primary bigbtn')}</div>${mesServer?`<div style="margin-top:10px">${button('取消',"serverEdit=false;serverError='';render()",'bigbtn')}</div>`:''}<p class="hint">当前为 UI 原型：仅保存地址，不请求真实服务器，也不会表示连接成功。正式版本须在连接检测和登录成功后进入作业。</p></section></div></div>`}
function saveServer(){let input=$('#serverAddress').value;try{let next=normalizeServer(input);let changed=mesServer&&mesServer!==next;localStorage.setItem(SERVERKEY,next);mesServer=next;serverEdit=false;serverError='';if(changed){wfCode='';wfChecked=false;wfTab='work'}render();toast('服务器地址已保存；尚未验证连接')}catch(e){serverError=e.message;render();$('#serverAddress').value=input;$('#serverAddress').focus()}}
function configureServer(){serverEdit=true;serverError='';closeModal();render()}
wfUserMenu=function(){modal('当前登录用户',detailRows([['姓名',escapeHtml(wfUser.name)],['工号',escapeHtml(wfUser.id)],['当前工位',stationId()+' · '+steps[wfStage]],['MES 服务器',escapeHtml(mesServer)],['连接状态','未验证 · 原型演示']]),button('服务器设置',"configureServer()")+button('返回管理后台',"closeModal();setMode('pc')")+button('切换用户',"wfLoginModal()",'primary'))};
render();

const wfJob={id:'MO-20261015-001',product:'P20 · 20W 快充充电宝',spec:'银灰 / 10000mAh',plan:2000};
const SCANKEY='power-mes-scan-events-v1';let scanLogs=[];try{scanLogs=JSON.parse(localStorage.getItem(SCANKEY)||'[]')}catch{}if(!Array.isArray(scanLogs))scanLogs=[];
function wfJobUnits(){return units.filter(u=>(u.order||wfJob.id)===wfJob.id)}
function wfNumbers(){let list=wfJobUnits();return {plan:wfJob.plan,station:list.filter(u=>wfStage===0?true:wfStage===1?!!u.cell:wfStage===2?!!lastPass(u):wfStage===3?!!u.sn:!!u.pack).length,finished:list.filter(u=>!!u.pack).length,failed:list.filter(u=>u.tests.length&&u.tests.at(-1).result==='FAIL').length}}
function wfOrderSummary(){let n=wfNumbers(),ratio=(n.station/n.plan*100).toFixed(1);return `<section class="panel station-order"><div class="panelhead"><div><h2>当前工单 · ${wfJob.id}</h2><p class="sub">${wfJob.product}　/　${wfJob.spec}　/　A01 产线</p></div>${badge('生产中')}</div>${stats([['工单计划数量',n.plan.toLocaleString()+' 台','该工单生产目标'],['本工位已完成',n.station.toLocaleString()+' 台',steps[wfStage]+' · 产品去重'],['工单成品已完成',n.finished.toLocaleString()+' 台','以包装码绑定完成为准'],['当前测试不合格',n.failed.toLocaleString()+' 台','按每台最新测试结果统计']])}<div class="summaryrow"><span>本工位完成进度 <b>${ratio}%</b></span><span class="sub">剩余 ${Math.max(0,n.plan-n.station).toLocaleString()} 台</span></div><div class="progress"><i style="width:${Math.min(100,Number(ratio))}%"></i></div><p class="hint">数量来自当前浏览器的演示工单记录；重复扫码和复测不增加产品数量。</p></section>`}
function wfLog(type,code,main,result,note){scanLogs.unshift({time:new Date().toLocaleString('zh-CN',{hour12:false}),order:wfJob.id,stage:wfStage,station:stationId(),user:wfUser.name+' / '+wfUser.id,type,code,main:main||'—',result,note});scanLogs=scanLogs.slice(0,200);localStorage.setItem(SCANKEY,JSON.stringify(scanLogs));render()}
function wfRecentPanel(){let recent=scanLogs.filter(x=>x.order===wfJob.id&&x.stage===wfStage).slice(0,10);return panel('最近扫码记录',table(['时间','操作类型','扫描条码','关联主码','结果','说明','操作人'],recent.length?recent.map(x=>[escapeHtml(x.time),escapeHtml(x.type),escapeHtml(x.code),escapeHtml(x.main),badge(x.result),escapeHtml(x.note),escapeHtml(x.user)]):[['—','—','—','—','—','本工位暂无扫码记录；扫码后自动显示','—']])+`<p class="hint">显示当前工单、当前工位最近 10 条记录，包含成功、重复与失败；仪器结果上传单独标注。</p>`,button('刷新',"render()"))}
const wfLookupBase=wfLookup;wfLookup=function(){let c=$('#wfScan').value.trim();if(!c){wfLookupBase();return}let before=units.find(u=>u.main===c||u.sn===c);wfLookupBase();let u=activeUnit(),valid=u&&(wfStage===4?u.sn===c:u.main===c);wfLog(wfStage===0?'主码过站':wfStage===4?'扫描 SN 查询':'扫描主码查询',c,u?.main,valid?(wfStage===0&&before?'重复扫码':'成功'):'失败',!valid?'条码不存在或不符合当前工位':wfStage===0&&before?'已过站，未重复计数':wfStage===0?'已建立过站记录':'已调出产品信息')};
const wfBindBase=wfBind;wfBind=function(kind,scannedCode){let u=activeUnit(),c=scannedCode||'',old=u?.[kind];wfBindBase(kind,scannedCode);if(!c)return;let success=!!u&&u[kind]===c&&u[kind]!==old;let note=success?'绑定记录已保存':$('#toast').textContent;wfLog({cell:'绑定电芯码',sn:'绑定 SN 码',pack:'绑定包装码'}[kind],c,u?.main,success?'成功':'失败',note)};
const wfTestBase=wfTest;wfTest=function(result){let u=activeUnit(),count=u?.tests.length||0;wfTestBase(result);if(u&&u.tests.length>count)wfLog('仪器自动上传',u.main,u.main,result,result==='PASS'?'测试合格，允许后续绑定':'测试不合格，禁止后续绑定')};
render();

function instrumentResults(){return wfJobUnits().flatMap((u,ui)=>u.tests.map((t,ti)=>({...t,main:u.main,_index:ui*10000+ti}))).sort((a,b)=>(b.timestamp||0)-(a.timestamp||0)||b._index-a._index)}
function instrumentStation(){return `<div class="stationbar"><div><b style="font-size:19px">◈ 智造 MES / 工位终端</b><p class="sub">A01-03 · 仪器测试</p></div><div class="actions">${button('⇄ 切换工位',"wfChooseStation()")}${button('⚙ 设置',"configureServer()")}${button(escapeHtml(wfUser.name)+' · '+escapeHtml(wfUser.id)+' ▾',"wfUserMenu()")}</div></div><div class="content">${heading('仪器测试工作站','接收仪器上传的测试结果，自动显示通过与失败信息')}${wfOrderSummary()}<div class="tabs">${button('测试结果',"wfTab='work';render()",wfTab!=='sop'&&wfTab!=='messages'?'active':'')}${button('SOP 指导书',"wfTab='sop';render()",wfTab==='sop'?'active':'')}${button('工位消息',"wfTab='messages';render()",wfTab==='messages'?'active':'')}</div>${wfTab==='sop'?wfSop():wfTab==='messages'?panel('工位消息',msgs.map((m,i)=>`<div class="lineitem"><div class="fill"><b>${escapeHtml(m.title)}</b><p class="sub">${escapeHtml(m.text)}</p></div>${button('查看',`messageDetail(${i})`)}</div>`).join('')):instrumentFeed()}<p class="hint">交互原型 · 当前仅显示演示记录，尚未连接真实仪器。</p></div>`}
function instrumentFeed(){let all=instrumentResults(),t=all[0];return panel('最新测试结果',t?`<div class="instrument-result ${t.result==='PASS'?'ispass':'isfail'}"><div class="result-symbol">${t.result==='PASS'?'✓':'×'}</div><div class="fill"><div class="eyebrow">${t.device||'ATE-001'} / ${escapeHtml(t.time)}</div><h1>${t.result==='PASS'?'测试通过 · PASS':'测试失败 · FAIL'}</h1><p>产品主码：<b>${escapeHtml(t.main)}</b></p><p class="sub">${t.result==='PASS'?'结果已记录，允许进入后续 SN 绑定工序。':'失败结果已保留，禁止后续绑定；复测另存记录。'}</p></div>${button('查看测试详情',"instrumentDetail(0)")}</div>`:`<div class="statusbox"><h2>等待仪器上传测试结果</h2><p class="sub">数据接收后自动展示，无需在平板输入条码。</p></div>`)+panel('历史测试结果',`<div class="test-history" id="testHistory" tabindex="0" aria-label="可滚动的历史测试结果">${table(['上传时间','产品主码','仪器','结果','测试记录','操作'],all.length?all.map((r,i)=>[escapeHtml(r.time),escapeHtml(r.main),escapeHtml(r.device||'ATE-001'),badge(r.result==='PASS'?'通过 · PASS':'失败 · FAIL'),escapeHtml(r.record),`<button class="link" onclick="instrumentDetail(${i})">详情</button>`]):[['—','—','—','—','暂无测试结果','—']])}</div><p class="hint">共 ${all.length} 条结果，向下滑动查看历史；PASS、FAIL 与复测记录全部保留。</p>`)}
function instrumentDetail(i){let t=instrumentResults()[i];if(!t)return;modal('测试记录详情',detailRows([['产品主码',escapeHtml(t.main)],['设备',escapeHtml(t.device||'ATE-001')],['记录编号',escapeHtml(t.record)],['时间',escapeHtml(t.time)],['测试判定',badge(t.result)]])+table(['测试项目','实测值','判定'],[['输出电压',escapeHtml(t.voltage)+' V',badge('PASS')],['输出电流',escapeHtml(t.current)+' A',badge(t.result)]]))}
// Demo device events originate in the admin panel, not the instrument terminal.
const apiBeforeDeviceDemo=renderers.api;renderers.api=function(){return apiBeforeDeviceDemo()+panel('仪器事件演示',`<p class="sub">在后台模拟外部仪器推送；工位端自动显示结果，不提供开始测试或条码查询操作。</p>${button('模拟仪器上传结果',"deviceEventDialog()",'primary')}`)};
function deviceEventDialog(){let eligible=wfJobUnits().filter(u=>u.cell&&!u.sn&&!u.pack);if(!eligible.length){toast('请先完成主码过站与电芯绑定，再模拟仪器上传');return}modal('模拟外部仪器上传',`<label class="field">测试产品<select id="deviceMain">${eligible.map(u=>`<option value="${escapeHtml(u.main)}">${escapeHtml(u.main)}</option>`).join('')}</select></label><label class="field" style="margin-top:15px">仪器判定<select id="deviceResult"><option>PASS</option><option>FAIL</option></select></label><p class="hint">仅模拟设备事件，不代表真实接入。</p>`,button('上传模拟结果',"submitDeviceEvent()",'primary'))}
function submitDeviceEvent(){let code=$('#deviceMain').value,result=$('#deviceResult').value,priorStage=wfStage,priorCode=wfCode;wfStage=2;wfCode=code;closeModal();wfTest(result);wfStage=priorStage;wfCode=priorCode;render()}
window.addEventListener('storage',e=>{if(e.key!==WFKEY&&e.key!==SCANKEY)return;let scroll=$('#testHistory')?.scrollTop||0;try{if(e.key===WFKEY){let data=JSON.parse(e.newValue||'[]');if(Array.isArray(data))units=data}else{let data=JSON.parse(e.newValue||'[]');if(Array.isArray(data))scanLogs=data}}catch{return}if(mode==='station'||mode==='screen'){render();if($('#testHistory'))$('#testHistory').scrollTop=scroll}});
render();

// One scanner input per workstation; an Enter/Tab suffix submits each scan.
let autoPending=false,autoStage=-1;
function wfAwaiting(){return autoStage===wfStage&&autoPending}
function wfExpected(){return wfAwaiting()?({1:'电芯码',3:'成品 SN',4:'包装码'}[wfStage]||'主码'):(wfStage===4?'成品 SN':'主码')}
function wfResetScan(){autoPending=false;autoStage=wfStage;wfCode='';wfChecked=false;render();wfFocus()}
function wfFocus(){if(mode==='station'&&wfStage!==2&&wfTab==='work'&&!$('#modal').innerHTML)$('#wfScan')?.focus()}
function wfAutoScan(){let c=$('#wfScan').value.trim();if(!c)return;if(autoStage!==wfStage){autoStage=wfStage;autoPending=false}if(autoPending){let kind={1:'cell',3:'sn',4:'pack'}[wfStage];if(!kind){autoPending=false;return}let u=activeUnit();if(!u){wfResetScan();return}if(wfStage===4)wfChecked=true;wfBind(kind,c);if(u[kind]===c){autoPending=false;render()}else render()}else{wfLookup();let u=activeUnit(),valid=u&&(wfStage===4?u.sn===c:u.main===c);autoPending=!!(valid&&(wfStage===1&&!u.cell||wfStage===3&&u.cell&&!u.sn&&lastPass(u)||wfStage===4&&u.sn&&!u.pack&&lastPass(u)));render()}wfFocus()}
const renderBeforeAutoScan=render;render=function(){renderBeforeAutoScan();wfFocus()};
const switchBeforeAutoScan=wfSwitchStation;wfSwitchStation=function(){autoPending=false;switchBeforeAutoScan();autoStage=wfStage;wfFocus()};
render();
